import{_ as s,c as a,o as i,b0 as o}from"./chunks/framework.BWMBvyU7.js";const d="/programming-docs/assets/1.9FTDt4ho.gif",n="/programming-docs/assets/2.DBta2Ksy.gif",u=JSON.parse('{"title":"LV005-信号量简介","description":null,"frontmatter":{"title":"LV005-信号量简介","date":"2026-03-16T21:40:04.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/os/process-communication/semaphore/126d38f372f40d9872c9985e","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-03-16T21:40:04.217Z","fulluuid":"872c9985e2e24cf0aa26077e990fb4c2","useduuid":"872c9985e"}},"headers":[],"relativePath":"sdoc/os/process-communication/semaphore/126d38f372f40d9872c9985e.md","filePath":"sdoc/03-操作系统/09-进程通信/25-信号量/LV005-信号量简介.md","lastUpdated":1773672539000}'),c={name:"sdoc/os/process-communication/semaphore/126d38f372f40d9872c9985e.md"};function l(p,e,t,r,h,k){return i(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="lv005-信号量简介" tabindex="-1">LV005-信号量简介 <a class="header-anchor" href="#lv005-信号量简介" aria-label="Permalink to &quot;LV005-信号量简介&quot;">​</a></h1><h2 id="一、信号量" tabindex="-1">一、信号量 <a class="header-anchor" href="#一、信号量" aria-label="Permalink to &quot;一、信号量&quot;">​</a></h2><p>其实前边我们在学习进程通信的时候，会不会有一个疑问，就是多个进程同时写一块区域的时候咋办？或者说那个进程在写，这个来读，读到的数据会不会就有问题呢？进程中没有像线程的互斥锁这些东西来保护共享的资源，但是我们可以使用信号量来达到相同的效果。</p><h3 id="_1-信号量简介" tabindex="-1">1. 信号量简介 <a class="header-anchor" href="#_1-信号量简介" aria-label="Permalink to &quot;1. 信号量简介&quot;">​</a></h3><p>信号量是一个计数器，与其它进程间通信方式不大相同，它主要用于<strong>控制多个进程间或一个进程内的多个线程间对共享资源的访问</strong>，相当于内存中的标志，进程可以根据它判定是否能够访问某些共享资源，同时，进程也可以修改该标志，除了用于共享资源的访问控制外，还可用于进程同步。</p><p>常被作为一种锁机制，防止某进程在访问资源时其它进程也访问该资源，因此，信号量主要作为进程间以及同一个进程内不同线程之间的同步手段，而不是用于缓存进程间通信的数据。</p><h3 id="_2-信号量的操作" tabindex="-1">2. 信号量的操作 <a class="header-anchor" href="#_2-信号量的操作" aria-label="Permalink to &quot;2. 信号量的操作&quot;">​</a></h3><p>信号量代表某一类资源，其值表示系统中该资源的数量，只能通过三种操作来访问它：</p><ul><li><p>（1）初始化</p></li><li><p>（2）<code>P</code>操作(申请资源)</p></li><li><p>（3）<code>V</code>操作(释放资源)</p></li></ul><p>【注意事项】<code>P</code> 操作是用在进入共享资源之前，<code>V</code> 操作是用在离开共享资源之后，这两个操作是<strong>必须成对出现</strong>的。</p><h4 id="_2-1-p-操作-申请资源" tabindex="-1">2.1 P 操作(申请资源) <a class="header-anchor" href="#_2-1-p-操作-申请资源" aria-label="Permalink to &quot;2.1 P 操作(申请资源)&quot;">​</a></h4><p><code>P</code>操作其实就是将信号量减去 <code>1</code>，相减后如果信号量<code>&lt; 0</code>，则表明资源已被占用，没有资源可用，进程需阻塞等待，进入等待队列；相减后如果信号量 <code>&gt;= 0</code>，则表明还有资源可使用，进程可正常继续执行。也就是</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">信号量的值 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(信号量的值 ≥ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{  </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> 	申请资源的任务继续运行;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">} </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{   </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	申请资源的任务阻塞,并插入等待队列;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br></div></div><h4 id="_2-2-v-操作-释放资源" tabindex="-1">2.2 V 操作(释放资源) <a class="header-anchor" href="#_2-2-v-操作-释放资源" aria-label="Permalink to &quot;2.2 V 操作(释放资源)&quot;">​</a></h4><p><code>V</code> 操作会把信号量加上 <code>1</code>，相加后如果信号量 <code>&lt;= 0</code>，则表明当前有阻塞中的进程，于是会从等待队列中取出一个进程唤醒运行；相加后如果信号量 <code>&gt; 0</code>，则表明当前没有阻塞中的进程。也就是</p><div class="language-c vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">信号量的值 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (信号量的值 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{   </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">	唤醒等待队列的一个任务，让其继续运行;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="_3-信号量种类" tabindex="-1">3. 信号量种类 <a class="header-anchor" href="#_3-信号量种类" aria-label="Permalink to &quot;3. 信号量种类&quot;">​</a></h3><p>一共有三种信号量，分别是<code>POXIX</code>中的无名信号量和有名信号量，以及<code>System V</code>信号量。</p><ul><li><p><code>POSIX</code>中的<strong>无名信号量主要用于线程间的通信</strong>，保存在内存中，如果想要在进程间同步就必须把无名信号量放在进程间的共享内存中。</p></li><li><p>而在<strong>进程间的通信中同步用的通常是有名信号量</strong>，有名信号量一般保存在<code>/dev/shm/</code> 目录下，它就像文件一样存储在文件系统中。</p></li><li><p><code>System V</code> 信号量是一个或多个计数信号量的集合，可同时操作集合中的多个信号量，并且申请多个资源时可以避免死锁。</p></li></ul><h2 id="二、互斥信号量" tabindex="-1">二、互斥信号量 <a class="header-anchor" href="#二、互斥信号量" aria-label="Permalink to &quot;二、互斥信号量&quot;">​</a></h2><p>上边的已经了解了信号量的操作，那具体是怎样工作的呢？比如我们现在有两个进程：进程<code>1</code>和进程<code>2</code>，还有一个信号量<code>sem</code>，我们将信号量<code>sem</code>初始化为<code>1</code>然后进程<code>1</code>和进程<code>2</code>都要访问共享内存。</p><img src="`+d+'" alt="2" style="zoom:60%;"><p>进程 <code>1</code>在访问共享内存前，先执行了 <code>P</code> 操作，信号量<code>sem</code>的初始值为 <code>1</code>，故在进程 <code>1</code> 执行 <code>P</code> 操作后信号量<code>sem</code>变为 <code>0</code>，表示共享内存可用，于是进程 <code>1</code> 就可以访问共享内存。</p><p>进程<code>1</code>正在访问共享内存，进程 <code>2</code> 也想访问共享内存，执行了 <code>P</code> 操作，会使信号量<code>sem</code>变为<code> -1</code>，这就意味着共享内存已被占用，因此进程 <code>2</code> 被阻塞。</p><p>当进程 <code>1</code> 访问完共享内存，才会执行 <code>V</code> 操作，使得信号量<code>sem</code>恢复为 <code>0</code>，接着就会唤醒阻塞中的线程 <code>2</code>，使得进程 <code>2</code> 可以访问共享内存，最后完成共享内存的访问后，执行 <code>V</code> 操作，信号量<code>sem</code>恢复到初始值 <code>1</code>。</p><p>由此我们知道，信号初始化为 <code>1</code>，就代表着是<strong>互斥信号量</strong>，它可以保证共享内存在任何时刻只有一个进程在访问，这就达到了保护了共享内存的目的。</p><h2 id="三、同步信号量" tabindex="-1">三、同步信号量 <a class="header-anchor" href="#三、同步信号量" aria-label="Permalink to &quot;三、同步信号量&quot;">​</a></h2><p>前边我们在学习线程的时候，有一个生产者与消费者的问题，生产者生产了产品后，消费者才能使用产品，进程之间是否也可以这样呢？我们假设有两个进程，分别为进程<code>1</code>和进程<code>2</code>，进程<code>1</code>负责生产产品，进程<code>2</code>负责使用产品，初始的信号量<code>sem</code>我们初始化为<code>0</code>。</p><img src="'+n+'" alt="2" style="zoom:60%;"><p>如果进程 <code>2</code> 比进程 <code>1</code> 先执行，那么执行到 <code>P</code> 操作时，而信号量<code>sem</code>初始值为 <code>0</code>，所以信号量<code>sem</code>会变为 <code>-1</code>，表示进程 <code>1</code> 还没生产产品，于是进程 <code>2</code> 就阻塞等待；</p><p>当进程 <code>1</code> 生产完产品后，执行了 <code>V </code>操作，就会使得信号量<code>sem</code>变为 <code>0</code>，于是就会唤醒阻塞在 <code>P</code> 操作的进程 <code>2</code>；</p><p>进程 <code>2</code> 被唤醒后，意味着进程 <code>1</code> 已经生产了数据，于是进程 <code>2</code> 就可以正常使用产品啦了。</p><p>由此可知，信号初始化为 <code>0</code>，就代表着是<strong>同步信号量</strong>，这样可以保证进程 <code>1</code> 应在进程 <code>2</code> 之前执行。</p>',33)])])}const E=s(c,[["render",l]]);export{u as __pageData,E as default};
